import io.nop.batch.dsl.TestCraR412DispatchMetricsE2E;
// 仅首 chunk 返回数据，其后空页终止（固定列表会无限循环）
if (TestCraR412DispatchMetricsE2E.served.compareAndSet(false, true)) {
    return [1, 2, 3];
}
return [];

